/* ============================================================================
 * 万象解析（key: jx）  —  易幕 / ekan-clone 源脚本  v1.0
 * ----------------------------------------------------------------------------
 * 这是什么：
 *   一个「解析接口源」。它做两件事：
 *     ① 搜索 —— 走两家采集站(暴风 bfzyapi / 量子 lziapi)的标准 MacCMS 接口；
 *     ② 播放 —— 把地址过一批解析接口，换成播放器真能播的 m3u8。
 *   它只用于搜索与播放，不参与首页浏览（homeSections 返回空）。
 *
 * 为什么这么设计（全部来自实测，不是推断）：
 *   - zy=ff/bf/lz 就是「非凡/暴风/量子」，与源名一一对应；
 *   - bfzyapi.com / cj.lziapi.com 实测 200 返回真片单（见 out/probe_chain*.txt）；
 *   - qgg.php 须同时带 zy + url 两个参数；
 *   - 缓存文件名 = md5(url)（两条样本逐字符命中）；
 *   - 服务端会把上游 404 的错误体当成 playlist 写进缓存，
 *     所以「拿到 url」不等于「可播」——必须校验首行 #EXTM3U。
 *     本脚本用 http.request2 拿 status+body 做这道闸门。
 *
 * 部署（三步）：
 *   1) 把本文件传到你的源脚本托管目录，例如 https://js.z1i.cn/ek/jx.js
 *   2) 在云控 config 的 sources.items[] 里加一条：
 *        { "key":"jx", "title":"解析", "desc":"", "enabled":true,
 *          "codeUrl":"https://js.z1i.cn/ek/jx.js", "codeVer":"1" }
 *      （「不在源列表显示」按你选的方案：只隐藏数据源管理页，见交付报告）
 *   3) 重进 App，搜索任意片名即可。
 *
 * 通过 ext 可覆盖（云控 item 里加 "ext":"<json 字符串>"）：
 *   { "sites":["bf","lz"], "zy":["lz","bf","ff"], "verifyDirect":true,
 *     "cacheFirst":false, "debug":false }
 *
 * 纪律：本文件不含任何客户端代码改动；不写死设备相关值。
 * ==========================================================================*/

/* ─────────────────────────── ext 配置 ─────────────────────────── */
var EXT = (typeof ext !== 'undefined' && ext) ? ext : {};
if (typeof EXT === 'string') { try { EXT = JSON.parse(EXT); } catch (e) { EXT = {}; } }
function cfgArr(k, dft) {
    var v = EXT[k];
    if (v instanceof Array && v.length) return v;
    if (typeof v === 'string' && v) { try { var p = JSON.parse(v); if (p instanceof Array && p.length) return p; } catch (e) {} }
    return dft;
}
function cfgBool(k, dft) { return (typeof EXT[k] === 'boolean') ? EXT[k] : dft; }
var DEBUG = cfgBool('debug', false);
var VERIFY_DIRECT = cfgBool('verifyDirect', true);
var VERIFY_CACHE = cfgBool('verifyCache', false);
var CACHE_FIRST = cfgBool('cacheFirst', false);
var SITE_ORDER = cfgArr('sites', ['bf', 'lz']);
var ZY_ORDER = cfgArr('zy', ['lz', 'bf', 'ff']);

var UA = 'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
/* 单请求超时。实测：qgg 命中缓存 ~0.1s、回源 0.4~0.6s；CMS 搜索 ~0.3~0.9s。
 * 取 12s 是给移动网络留余量，同时不至于让「一条挂掉的端点」拖死整条链。 */
var TIMEOUT = Number(EXT.timeout) > 0 ? Number(EXT.timeout) : 12000;

/* ─────────────────────────── 基础工具 ─────────────────────────── */
function t(v) { return v == null ? '' : String(v); }
function trim(v) { return t(v).replace(/^\s+|\s+$/g, ''); }
function enc(v) { try { return encodeUri(t(v)); } catch (e) { try { return encodeURIComponent(t(v)); } catch (e2) { return t(v); } } }
function md5hex(v) {
    try { return t(md5(t(v))).toLowerCase(); } catch (e) {}
    try { return t(crypto.hash('MD5', t(v), { input: 'utf8', output: 'hex' })).toLowerCase(); } catch (e2) { return ''; }
}
function jparse(s, dft) { try { if (typeof parseJson === 'function') { var o = parseJson(t(s)); if (o) return o; } } catch (e) {} try { return JSON.parse(t(s)); } catch (e2) { return dft == null ? null : dft; } }
function dbg(msg) { if (DEBUG) { try { log('[jx] ' + msg); } catch (e) {} } }

/* 同步 GET：返回 body 字符串（失败返回空串）。tries 用于 CMS 这类「抖一下就没了」的请求。 */
function httpGet(url, headers, tries) {
    var o = { headers: headers || { 'User-Agent': UA, 'Referer': 'https://js.z1i.cn/' }, timeout: TIMEOUT };
    var n = tries && tries > 0 ? tries : 1;
    for (var i = 0; i < n; i++) {
        try { var r = request(url, JSON.stringify(o)); if (r != null && t(r).length) return t(r); } catch (e) { dbg('GET fail ' + url.slice(0, 80) + ' | ' + e); }
    }
    return '';
}
/* 同步 GET：返回 {status, ok, body}，用于校验闸门 */
function httpProbe(url) {
    try {
        if (typeof http !== 'undefined' && http && typeof http.request2 === 'function') {
            var r = http.request2(url, JSON.stringify({ headers: { 'User-Agent': UA }, timeout: TIMEOUT }));
            if (r && typeof r === 'object') return { status: Number(r.status || 0), ok: !!r.ok, body: t(r.body == null ? '' : r.body) };
        }
    } catch (e) { dbg('probe2 fail | ' + e); }
    var b = httpGet(url);
    return { status: b ? 200 : 0, ok: !!b, body: b };
}

/* ─────────────────────────── 采集站表（内容/搜索） ───────────────────────────
 * 对应关系来自实测：zy=bf↔暴风, zy=lz↔量子。
 * lz 走 http —— 其 https 入口实测会间歇 UNEXPECTED_EOF。 */
var SITES = {
    bf: { key: 'bf', name: '暴风', zy: 'bf', cms: 'https://bfzyapi.com' },
    lz: { key: 'lz', name: '量子', zy: 'lz', cms: 'http://cj.lziapi.com' }
};

/* ─────────────────────────── 解析接口登记表 ───────────────────────────
 * url 模板已含参数名，直接拼「编码后的目标地址」即可。
 * fields：从响应 JSON 里按顺序取址的字段路径。
 * caps  ：吃哪种输入 —— 'url' 普通地址 / 'cipher' xfy- 密文。缺省视为 url。
 * by    ：实测结论（取自 out/probe_matrix.txt，不美化）。
 * off   ：默认停用；改 off:true→false 即可启用（实测失败原因见 by）。 */
var ENDPOINTS = [
    /* —— A 档：本次样本上实测解出真 playlist（唯一一批）—— */
    { id: 'qgg', name: '咕噜·量子', url: 'http://111.170.58.215:7788/qgg.php?zy=lz&url=', fields: ['url'], by: 'A 实测出真playlist', zy: 'lz', group: 'qgg' },
    { id: 'qgg', name: '咕噜·暴风', url: 'http://111.170.58.215:7788/qgg.php?zy=bf&url=', fields: ['url'], by: 'A 实测出真playlist', zy: 'bf', group: 'qgg' },
    { id: 'qgg', name: '咕噜·非凡', url: 'http://111.170.58.215:7788/qgg.php?zy=ff&url=', fields: ['url'], by: 'A 实测出真playlist', zy: 'ff', group: 'qgg' },

    /* —— B 档：存活、参数契约清楚，但本次样本上未产出可播地址 —— */
    { id: 'glgltos', name: 'glgltos', url: 'http://122.228.193.79:6699/glgltos.php?url=', fields: ['main_url', 'url'], by: 'B 存活未产出（唯一吃 xfy- 密文的）', caps: ['cipher', 'url'] },
    { id: 'dsxtC', name: 'dsxt-C', url: 'http://172.247.189.48:7788/dsxt/api.php?user=xt&key=969632c8da19b3ef8c56e5b51011d5e0&j=19227eae77225a30&url=', fields: ['url', 'data.url'], by: 'B 存活未产出（有每日额度）' },
    { id: 'nbyjson', name: 'nbyjson', url: 'https://api.nbyjson.top:7788/api/?key=8LJohkjTZHC2F9ct48&url=', fields: ['url', 'data.url'], by: 'B 存活未产出（只吃自家采集数据）', off: true },
    { id: 'dsxtA', name: 'dsxt-A', url: 'http://172.247.189.48:7788/dsxt/api.php?user=xt&key=e1234a9df0358c6d78f20721a1b7b055&j=b8582063bca37121&url=', fields: ['url', 'data.url'], by: 'B 存活但上游回源要 15s 超时 —— 默认关，否则拖死整条链', off: true },
    { id: 'hxx', name: 'hxx2023', url: 'https://jf.hxx2023.cc/api?key=Uw5rZokFSAywqcLN&url=', fields: ['url'], by: 'B 存活未产出', off: true },
    { id: 'jdyx', name: 'jdyx', url: 'https://jiexi.jdyx.pro/api/?key=8a94da668d980bae94fbc8dd3fd115ce&url=', fields: ['url', 'data.url'], by: 'B 存活未产出', off: true },
    { id: 'co4k', name: 'co4k', url: 'https://co4k.1ljx.com:32010/api/?key=6db7285d-c228-4cee-918e-67a01ef7c3f8&url=', fields: ['url', 'data.url'], by: 'B 返回的址 HTTP 404', off: true },
    { id: 'huaqi', name: 'huaqi', url: 'https://api.huaqi.pro/api?key=29f6670f4bf121162d337d9171689a10&url=', fields: ['url'], by: 'B 存活未产出', off: true },
    { id: 'p4470', name: '4470', url: 'http://111.170.58.215:4470/api.php?id=', fields: ['url', 'data.url'], by: 'B 存活未产出（参数名是 id 不是 url）', off: true },
    { id: 'kz3821', name: 'KZNBJX-3821', url: 'http://122.228.193.79:3821/KZNBJX.php?url=', fields: ['url'], by: 'B 回 不支��的解析', off: true },
    { id: 'kz3721', name: 'KZNBJX-3721', url: 'http://122.228.193.79:3721/KZNBJX.php?url=', fields: ['url'], by: 'B 回 不支持的解析', off: true },

    /* —— C 档：实测不可用，保留只为「别再踩进来」 —— */
    { id: 'dsxtB', name: 'dsxt-B', url: 'http://172.247.44.102:7788/dsxt/api.php?user=xt&key=118066f4cea9d46ce2187c136ffc77a6&j=f96409e57ad0db3e&url=', fields: ['url'], by: 'C 502 upstream timeout', off: true },
    { id: 'xfy', name: 'xfyvideochandi', url: 'https://xfyvideochandi.online/p.php?id=', fields: ['url'], by: 'C 超时无响应', off: true },
    { id: 'coffee', name: 'coffee-api', url: 'https://coffee-api.1ljx.com/api/?key=a6e68ade-8d4b-4ef3-8cb3-753a5e01d5fa&url=', fields: ['url'], by: 'C 403 IP白名单（客户端 IP 进不去）', off: true }
];

/* ─────────────────────────── 地址性质判定 ─────────────────────────── */
function isMedia(u) { return /\.(m3u8|mp4|flv|mkv|m4s|mpd)(?:[?#]|$)/i.test(t(u)); }
function isCipher(u) { return /^xfy-/i.test(t(u)); }
function isHttp(u) { return /^https?:\/\//i.test(t(u)); }
function mediaType(u) {
    var s = t(u); if (/\.m3u8(?:[?#]|$)/i.test(s)) return 'm3u8';
    if (/\.mp4(?:[?#]|$)/i.test(s)) return 'mp4';
    if (/\.flv(?:[?#]|$)/i.test(s)) return 'flv';
    if (/\.m4s(?:[?#]|$)/i.test(s)) return 'm4s';
    return 'auto';
}
function looksLikeHtml(r) {
    var b = t(r && r.body).replace(/^\uFEFF/, '').replace(/^\s+/, '').toLowerCase();
    return b.indexOf('<!doctype') === 0 || b.indexOf('<html') === 0 || b.indexOf('<head') === 0;
}
/* 严格判据：响应体本身就是一条 playlist（用于判定「目标地址直连能不能播」） */
function isValidBody(r) {
    if (!r) return false;
    if (r.status && (r.status < 200 || r.status >= 400)) return false;
    var b = t(r.body).replace(/^\uFEFF/, '').replace(/^\s+/, '');
    return b.indexOf('#EXTM3U') === 0;
}

/* 宽判据：这个地址交给播放器之前，先确认它真是一条 playlist。
 * 这是本脚本最值钱的一处 —— 服务端会把上游 404 的错误体当 playlist 缓存，
 * 接口照样回 code:200，不校验就会黑屏。实测现场见 out/probe_matrix.txt T2。 */
function isValidPlaylist(u) {
    if (!isHttp(u)) return false;
    var r = httpProbe(u);
    if (isValidBody(r)) return true;
    /* 容忍「响应体是 JSON 且其 url 字段是 m3u8」这种中转形态 */
    var b = t(r.body).replace(/^\s+/, '');
    if (b.charAt(0) === '{' || b.charAt(0) === '[') {
        var o = jparse(b, null);
        if (o) { var d = digUrl(o); if (d && /\.m3u8([?#]|$)/i.test(d)) return true; }
    }
    return false;
}

/* 从解析接口响应里挖出地址：先按字段路径，再退化到正则扫 "url":"..." */
function digUrl(o) {
    if (!o || typeof o !== 'object') return '';
    var paths = ['url', 'data.url', 'main_url', 'data.main_url', 'json.url', 'data', 'play_url', 'vurl'];
    for (var i = 0; i < paths.length; i++) {
        var cur = o, parts = paths[i].split('.'), ok = true;
        for (var j = 0; j < parts.length; j++) {
            if (cur && typeof cur === 'object' && cur[parts[j]] != null) cur = cur[parts[j]]; else { ok = false; break; }
        }
        if (ok) {
            var s = t(cur);
            if (s && isHttp(s)) return s;
            if (s && /\.m3u8([?#]|$)/i.test(s)) return s;
        }
    }
    return '';
}
function extractUrl(body) {
    var s = trim(t(body));
    if (!s) return '';
    if (s.indexOf('#EXTM3U') === 0) return '';      /* 响应体即 playlist：交给调用方按模板处理 */
    var o = jparse(s, null);
    if (o) { var u = digUrl(o); if (u) return u; }
    var m = s.match(/https?:\/\/[^\s"'\\<>]+\.m3u8[^\s"'\\<>]*/i);
    if (m) return m[0].replace(/\\\//g, '/');
    return '';
}

/* 本地结果缓存：key = md5(原始地址)。命中就省掉整条链路。 */
function ck(u) { return 'jxc:' + md5hex(u); }
function cGet(u) { try { return t(getItem(ck(u), '')); } catch (e) { return ''; } }
function cPut(u, v) { try { if (v) setItem(ck(u), v); } catch (e) {} }

/* 服务端把上游失败也写进缓存，且不自愈（实测：cache=yes 的污染缓存会一直返回错误体）。
 * 同一 md5 在各 zy 目录下会被一起污染，所以同组其余档位再试也是白费。 */
function isPoisoned(body) { var o = jparse(trim(body), null); return !!(o && t(o.cache) === 'yes'); }

/* ─────────────────────────── 解析主链 ─────────────────────────── */
/* 把 target 依次喂给启用的解析接口，返回第一个「通过校验闸门」的地址。
 * shape='cipher' 时只喂标记了 caps:['cipher'] 的端点（密文不是 URL，喂给 URL 型接口只会得到「无效的URL格式」）。 */
function parseChain(target, shape) {
    var out = '', skipped = {};
    for (var i = 0; i < ENDPOINTS.length && !out; i++) {
        var ep = ENDPOINTS[i];
        if (ep.off) continue;
        if (ep.group && skipped[ep.group]) { dbg('跳过 ' + ep.name + '（同组缓存已污染）'); continue; }
        var caps = ep.caps || ['url'];
        if (shape === 'cipher') { if (caps.indexOf('cipher') < 0) continue; }
        else { if (caps.indexOf('url') < 0) continue; }
        var req = ep.url + enc(target);
        var body = httpGet(req);
        if (!body) { dbg(ep.name + ' 空响应'); continue; }
        if (trim(body).indexOf('#EXTM3U') === 0) { out = req; break; }        /* 响应体即 playlist：把接口地址直接当播放地址 */
        var cand = extractUrl(body);
        if (!cand) {
            dbg(ep.name + ' 无址: ' + trim(body).slice(0, 60));
            if (ep.group && isPoisoned(body)) skipped[ep.group] = 1;
            continue;
        }
        if (!VERIFY_DIRECT || isValidPlaylist(cand)) { out = cand; break; }
        dbg(ep.name + ' 址不可播: ' + cand.slice(0, 70));
        if (ep.group && isPoisoned(body)) skipped[ep.group] = 1;
    }
    return out;
}

/* 自算远端缓存直取：Cache/<ZY 大写>/<md5(url)>.m3u8（实测规则） */
function tryRemoteCache(target) {
    var h = md5hex(target);
    if (!h) return '';
    for (var i = 0; i < ZY_ORDER.length; i++) {
        var cu = 'http://111.170.58.215:7788/Cache/' + t(ZY_ORDER[i]).toUpperCase() + '/' + h + '.m3u8';
        var r = httpProbe(cu);
        if (r.status === 200 && t(r.body).replace(/^\s+/, '').indexOf('#EXTM3U') === 0) return cu;
    }
    return '';
}

/* ─────────────────────────── 采集站访问 ─────────────────────────── */
function cmsApi(site, query) { return site.cms + '/api.php/provide/vod/?' + query; }
function cmsHeaders(site) { return { 'User-Agent': UA, 'Referer': site.cms + '/' }; }

function cmsSearch(site, kw, page) {
    var url = cmsApi(site, 'ac=detail&wd=' + enc(kw) + '&pg=' + Math.max(1, Number(page) || 1));
    var raw = httpGet(url, cmsHeaders(site), 2);          /* 采集站会偶发空响应，重试一次 */
    var o = jparse(raw, null);
    if (!o) { dbg(site.name + ' 搜索非JSON: ' + raw.slice(0, 60)); return []; }
    var list = o.list instanceof Array ? o.list : [];
    return list;
}
function cmsDetail(site, vid) {
    var url = cmsApi(site, 'ac=detail&ids=' + enc(vid));
    var raw = httpGet(url, cmsHeaders(site), 2);
    var o = jparse(raw, null);
    if (!o || !(o.list instanceof Array) || !o.list.length) {
        dbg(site.name + ' 详情失败 url=' + url + ' rawLen=' + t(raw).length + ' head=' + t(raw).slice(0, 140));
        return null;
    }
    return o.list[0];
}

/* id 形如 "bf:139597"，用站点前缀区分两家 */
function makeId(siteKey, vid) { return siteKey + ':' + t(vid); }
function parseId(id) {
    var s = trim(id), i = s.indexOf(':');
    if (i > 0) {
        var k = s.substring(0, i);
        if (SITES[k]) return { site: SITES[k], vid: s.substring(i + 1) };
    }
    return { site: SITES[SITE_ORDER[0]], vid: s };
}

/* ─────────────────────────── 源契约 ─────────────────────────── */
function config() { return JSON.stringify({ kind: 'video', browseOnly: false, source: '解析' }); }
function categories() { return '[]'; }
function homeSections() { return '[]'; }
function searchFiltered() { return '[]'; }
function related() { return '[]'; }

function cardOf(site, v) {
    v = v || {};
    var id = v.vod_id != null ? v.vod_id : v.id;
    if (id == null || id === '') return null;
    var name = trim(v.vod_name || v.name || v.title);
    if (!name) return null;
    var desc = trim(v.vod_blurb || v.vod_content || v.desc || '');
    if (desc.length > 180) desc = desc.substring(0, 180);
    return { id: makeId(site.key, id), name: name,
             pic: trim(v.vod_pic || v.pic || ''),
             type: trim(v.vod_class || v.type_name || v.type || ''),
             year: t(v.vod_year || v.year || ''),
             remarks: trim(v.vod_remarks || v.remarks || ''), desc: desc };
}

function search(keyword, page) {
    var kw = trim(keyword);
    if (!kw) return '[]';
    var p = Math.max(1, Number(page) || 1), out = [], seen = {}, CAP = 60;
    for (var i = 0; i < SITE_ORDER.length && out.length < CAP; i++) {
        var site = SITES[SITE_ORDER[i]];
        if (!site) continue;
        var list = cmsSearch(site, kw, p);
        for (var j = 0; j < list.length && out.length < CAP; j++) {
            var c = cardOf(site, list[j]);
            if (!c) continue;
            var dedup = c.name + '|' + c.id;
            if (seen[dedup]) continue;
            seen[dedup] = 1;
            out.push(c);
        }
    }
    dbg('search "' + kw + '" p' + p + ' -> ' + out.length + ' 条');
    return JSON.stringify(out);
}

function detail(id) {
    var ref = parseId(id);
    var v = cmsDetail(ref.site, ref.vid);
    if (!v) return JSON.stringify({ id: t(id), name: '', pic: '', episodes: [] });

    var froms = t(v.vod_play_from).split('$$$');
    var groups = t(v.vod_play_url).split('$$$');

    /* 组优先级：组名含 m3u8 的是直连媒体，排前面；
     * 实测「量子」组0=liangzi 是分享页(HTML，所有接口都解不了)，
     * 组1=lzm3u8 才是直连 m3u8 —— 不排序就会把死路当默认线路。 */
    var order = [];
    for (var g = 0; g < groups.length; g++) {
        var gname = trim(froms[g]) || ('线路' + (g + 1));
        var score = /m3u8/i.test(gname) ? 0 : (/m3u|hls/i.test(gname) ? 1 : 2);
        order.push({ i: g, name: gname, score: score });
    }
    order.sort(function (a, b) { return a.score - b.score || a.i - b.i; });

    var eps = [], usedUrl = {};
    for (var o = 0; o < order.length; o++) {
        var gi = order[o].i, gname2 = order[o].name;
        var items = t(groups[gi]).split('#');
        var n = 0;
        for (var k = 0; k < items.length; k++) {
            var it = trim(items[k]);
            if (!it) continue;
            var pos = it.indexOf('$'), nm, u;
            if (pos >= 0) { nm = trim(it.substring(0, pos)); u = trim(it.substring(pos + 1)); }
            else { nm = ''; u = it; }
            if (!u) continue;
            n++;
            if (!nm) nm = '第' + n + '集';
            /* episode.url 会被下载队列与列表 key 消费，必须保持原始地址，不能打包 */
            if (usedUrl[u]) continue;
            usedUrl[u] = 1;
            eps.push({ name: nm, url: u, route: ref.site.name + '·' + gname2 });
        }
    }

    var out = { id: t(id),
                name: trim(v.vod_name || v.name || ''),
                pic: trim(v.vod_pic || ''),
                type: trim(v.vod_class || v.type_name || ''),
                year: t(v.vod_year || ''),
                remarks: trim(v.vod_remarks || ''),
                desc: (trim(v.vod_content || v.vod_blurb || '')).substring(0, 300) };
    out.episodes = eps;
    dbg('detail ' + t(id) + ' -> ' + eps.length + ' 集 / ' + order.length + ' 线路');
    return JSON.stringify(out);
}

/* 统一的返回值构造。
 * userAgent 与 headers 同时给：客户端 parsePlay 读 userAgent，多数源脚本用 headers，
 * 两条通道都铺上，避免因字段名不同导致 UA 丢失。 */
function outPlay(u) {
    return JSON.stringify({ url: u, type: mediaType(u), userAgent: UA, headers: { 'User-Agent': UA } });
}

function play(flag) {
    var u = trim(flag);
    if (!u) return JSON.stringify({ url: '', type: 'auto' });

    /* 0) 本地结果缓存：只缓存「需要解析才有答案」的地址。
     * 写入时已过校验闸门，默认不再复验（否则缓存等于白做）；要复验置 ext.verifyCache=true。 */
    var hit = cGet(u);
    if (hit && (!VERIFY_CACHE || isValidPlaylist(hit))) { dbg('本地缓存命中'); return outPlay(hit); }

    /* 1) 一次探测，同时完成两件事：判「直连能不能播」+ 判「地址是什么形态」 */
    var shape = 'unknown';
    if (isCipher(u)) {
        shape = 'cipher';
    } else if (isHttp(u)) {
        if (!VERIFY_DIRECT && isMedia(u)) { dbg('直连(未校验)'); return outPlay(u); }
        var pr = httpProbe(u);
        if (isValidBody(pr)) { dbg('直连可播'); return outPlay(u); }
        shape = looksLikeHtml(pr) ? 'page' : 'media';
        dbg('直连不可播 shape=' + shape);
    }

    /* 2) 可选：自算远端缓存直取（命中零上游） */
    if (CACHE_FIRST && isHttp(u)) {
        var rc = tryRemoteCache(u);
        if (rc) { cPut(u, rc); dbg('远端缓存直取命中'); return outPlay(rc); }
    }

    /* 3) 解析链。
     * shape='page' 直接跳过 —— 实测六条接口对 HTML 页面全部失败，跑一遍纯属白等 3~18s。
     * 网页交给第 4 步的端内嗅探，那才是它的正解。 */
    if (shape !== 'page') {
        var got = parseChain(u, shape === 'cipher' ? 'cipher' : 'url');
        if (got) { cPut(u, got); return outPlay(got); }
    }

    /* 4) 端内嗅探兜底（依赖 App 的 WebView 嗅探，与解析接口互补，对网页最有用） */
    try {
        if (typeof sniffMedia === 'function') {
            var s = sniffMedia(u, { timeout: TIMEOUT });
            if (s && s.ok && s.url) { cPut(u, s.url); dbg('sniffMedia 命中'); return outPlay(s.url); }
        }
    } catch (e) { dbg('sniff 失败 ' + e); }

    /* 5) 诚实失败：交回客户端走它自己的换���/回退，不硬塞一个假地址 */
    dbg('全部解析失败: ' + u.slice(0, 80));
    return JSON.stringify({ url: '', type: 'auto' });
}
